             if (actualFormat.equals("png") && ext.equals("png")) matches = true;
             else if (actualFormat.equals("jpg") && (ext.equals("jpg") || ext.equals("jpeg"))) matches = true;
             else if (actualFormat.equals("gif") && ext.equals("gif")) matches = true;
