   @Override
   public void afterCheckEachProject(@NonNull Context context) {
       Project project = context.getProject();
       for (File resFolder : project.getResourceFolders()) {
           File[] drawables = resFolder.listFiles(file -> file.isDirectory() && file.getName().startsWith("drawable"));
           if (drawables == null) continue;
           for (File drawableDir : drawables) {
               Map<String, File> baseNames = new HashMap<>();
               File[] files = drawableDir.listFiles();
               if (files == null) continue;
               for (File f : files) {
                   String name = f.getName();
                   if (name.endsWith(".png") || name.endsWith(".9.png")) {
                       String base;
                       if (name.endsWith(".9.png")) {
                           base = name.substring(0, name.length() - 6);
                       } else {
                           base = name.substring(0, name.length() - 4);
                       }
                       File existing = baseNames.put(base, f);
                       if (existing != null) {
                           // Clash detected
                           String msg = String.format("Clashing PNG and 9-PNG files: `%s` and `%s` both map to `@drawable/%s`",
                                   existing.getName(), f.getName(), base);
                           context.report(ISSUE, Location.create(f), msg);
                           // Also report on the existing file? Usually one incident is enough.
                       }
                   }
               }
           }
       }
   }
