@Override
public void afterCheckEachProject(@NonNull Context context) {
    Project project = context.getProject();
    List<File> resourceFolders = project.getResourceFolders();
    for (File resFolder : resourceFolders) {
        File[] drawables = resFolder.listFiles(file -> file.isDirectory() && file.getName().startsWith("drawable"));
        if (drawables == null) continue;
        for (File drawableDir : drawables) {
            Map<String, File> pngFiles = new HashMap<>();
            Map<String, File> ninePatchFiles = new HashMap<>();
            File[] files = drawableDir.listFiles();
            if (files == null) continue;
            for (File f : files) {
                String name = f.getName();
                if (name.endsWith(".9.png")) {
                    String base = name.substring(0, name.length() - 6);
                    ninePatchFiles.put(base, f);
                } else if (name.endsWith(".png")) {
                    String base = name.substring(0, name.length() - 4);
                    pngFiles.put(base, f);
                }
            }
            for (String base : pngFiles.keySet()) {
                if (ninePatchFiles.containsKey(base)) {
                    File png = pngFiles.get(base);
                    File ninePatch = ninePatchFiles.get(base);
                    String msg = String.format("Both `%s` and `%s` exist in the same folder, which will clash as `@drawable/%s`", png.getName(), ninePatch.getName(), base);
                    context.report(ISSUE, Location.create(png), msg);
                    context.report(ISSUE, Location.create(ninePatch), msg);
                }
            }
        }
    }
}
