   private void checkWebp(Context context, UElement node, String value) {
       if (value == null) return;
       String lower = value.toLowerCase();
       if (!lower.endsWith(".webp")) return;

       int minSdk = context.getMainProject().getMinSdkVersion().getApiLevel();
       boolean isLosslessOrAlpha = lower.contains("_lossless") || lower.contains("_alpha") || lower.contains("_trans");

       if (minSdk < 15) {
           context.report(ISSUE, node, context.getLocation(node), "WebP requires API level 15 (current min is " + minSdk + ")");
       } else if (isLosslessOrAlpha && minSdk < 18) {
