   @Override
   public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
       NamedNodeMap attributes = element.getAttributes();
       for (int i = 0; i < attributes.getLength(); i++) {
           Node attr = attributes.item(i);
           String value = attr.getNodeValue();
           if (value != null && value.toLowerCase().endsWith(".webp")) {
               int minSdk = context.getMainProject().getMinSdkVersion().getApiLevel();
               boolean isLosslessOrAlpha = value.toLowerCase().contains("_lossless") || value.toLowerCase().contains("_alpha");
               if (minSdk < 15) {
