                   if ("LEFT".equals(name) || "RIGHT".equals(name)) {
                       context.report(ISSUE, node, context.getLocation(node),
                               "Consider using `START`/`END` or ensure symmetric padding/margins for RTL support");
                   }
               }
           };
       }
