     private Set<String> getRegisteredComponents(File manifest, String packageName) {
         Set<String> registered = new HashSet<>();
         try {
             DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
             factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
             DocumentBuilder builder = factory.newDocumentBuilder();
             Document doc = builder.parse(manifest);
             NodeList activities = doc.getElementsByTagName("activity");
             NodeList services = doc.getElementsByTagName("service");
             NodeList providers = doc.getElementsByTagName("provider");
             // process each
             for (NodeList list : Arrays.asList(activities, services, providers)) {
                 for (int i = 0; i < list.getLength(); i++) {
                     Element el = (Element) list.item(i);
                     String name = el.getAttribute("android:name");
                     if (name != null && !name.isEmpty()) {
                         registered.add(resolveClassName(name, packageName));
                     }
                 }
             }
         } catch (Exception e) {
             // ignore
         }
         return registered;
     }
     ```
