                       line.contains("android:name=\"." + simpleName + "\"") ||
                       line.contains("android:name=\"" + simpleName + "\"")) {
                       return true;
                   }
               }
           } catch (IOException e) {
               // If we can't read the manifest, assume it's registered to avoid false positives
               return true;
           }
           return false;
       }

