   public class AndroidAutoDetector extends Detector implements Detector.SourceCodeScanner, Detector.XmlScanner {

       private static final Implementation IMPLEMENTATION =
               new Implementation(AndroidAutoDetector.class, EnumSet.of(Scope.JAVA_FILE, Scope.RESOURCE_FILE));

       public static final Issue ISSUE =
               Issue.create(
                       "MissingIntentFilterForMediaSearch",
                       "Missing MEDIA_PLAY_FROM_SEARCH intent-filter",
                       "To support voice searches on Android Auto, you should also register an intent-filter for the action android.media.action.MEDIA_PLAY_FROM_SEARCH. To do this, add an intent-filter with this action to your activity or service.",
                       Category.CORRECTNESS,
                       6,
                       Severity.ERROR,
                       IMPLEMENTATION);

