       private boolean isMediaService(@NonNull XmlContext context, @NonNull String name) {
           String pkg = context.getProject().getPackage();
           String fqn = name;
           if (pkg != null) {
               if (name.startsWith(".")) {
                   fqn = pkg + name;
               } else if (name.indexOf('.') == -1) {
                   fqn = pkg + "." + name;
               }
           }
           return mMediaServices.contains(fqn);
       }

