           layoutToIdLocations.computeIfAbsent(layoutName, k -> new HashMap<>())
               .putIfAbsent(id, context.getLocation(attribute));
       } else if ("layout".equals(localName) && "include".equals(attribute.getOwnerElement().getTagName())) {
