           if (value != null) {
               if (value.contains("always")) {
                   mXmlAlwaysCount++;
               }
               if (value.contains("ifRoom")) {
                   mXmlIfRoomCount++;
               }
           }
       }

       @Override
       public void afterCheckFile(@NonNull Context context) {
           if (context instanceof XmlContext) {
               if (mXmlAlwaysCount > 2 || (mXmlAlwaysCount > 0 && mXmlIfRoomCount == 0)) {
