                   Element root = xmlContext.getDocument().getDocumentElement();
                   if (root != null) {
                       xmlContext.report(ISSUE, root, xmlContext.getLocation(root),
                           "Consider using `ifRoom` instead of `always`");
                   }
               }
           }
