    public Collection<String> getApplicableElements() {
        return null; // Visit all elements
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tagName = element.getTagName();
        if (VALID_TAGS.contains(tagName)) {
            return;
        }

        String suggestion = findClosestTag(tagName);
        if (suggestion != null) {
            String message = String.format("Suspicious tag name `%1$s`: did you mean `%2$s`?", tagName, suggestion);
            LintFix fix = fix().replace().text(tagName).with(suggestion).build();
            context.report(ISSUE, element, context.getLocation(element), message, fix);
        }
    }

