           for (UMethod constructor : declaration.getConstructors()) {
               List<UParameter> parameters = constructor.getParameters();
               int count = parameters.size();
               if (count == 1 && isContext(parameters.get(0).getType())) {
                   hasValidConstructor = true;
                   break;
               } else if (count == 2 && isContext(parameters.get(0).getType())
                       && isAttributeSet(parameters.get(1).getType())) {
                   hasValidConstructor = true;
                   break;
               } else if (count == 3 && isContext(parameters.get(0).getType())
                       && isAttributeSet(parameters.get(1).getType())
                       && isInt(parameters.get(2).getType())) {
                   hasValidConstructor = true;
                   break;
               }
           }

           if (!hasValidConstructor) {
               context.report(ISSUE, declaration, context.getNameLocation(declaration),
                       "Missing View constructor for XML inflation");
           }
       }

       private static boolean isContext(PsiType type) {
           return type != null && "android.content.Context".equals(type.getCanonicalText());
       }

       private static boolean isAttributeSet(PsiType type) {
           return type != null && "android.util.AttributeSet".equals(type.getCanonicalText());
       }

       private static boolean isInt(PsiType type) {
           return type != null && type.equalsToText("int");
       }
   }
